def check_random_state(seed):
    """Turn seed into a np.random.RandomState instance.

    Parameters
    ----------
    seed : None, int, or np.random.RandomState
    """
    if seed is None or seed is np.random:
        return np.random.mtrand._rand
    if isinstance(seed, (int, np.integer)):
        return np.random.RandomState(seed)
    if isinstance(seed, np.random.RandomState):
        return seed
    raise ValueError("%r cannot be used to seed a RandomState instance" % seed)


def check_is_fitted_full(estimator, attributes=None, msg=None, all_or_any=all):
    """Raise NotFittedError if not fitted (full signature)."""
    if msg is None:
        msg = ("This %(name)s instance is not fitted yet. Call 'fit' first."
               % {'name': type(estimator).__name__})
    if attributes is not None:
        if isinstance(attributes, str):
            attributes = [attributes]
        if not all_or_any([hasattr(estimator, attr) for attr in attributes]):
            raise NotFittedError(msg)
    else:
        fitted_attrs = [a for a in vars(estimator)
                        if a.endswith('_') and not a.startswith('__')]
        if not fitted_attrs:
            raise NotFittedError(msg)


check_is_fitted = check_is_fitted_full


def column_or_1d(y, dtype=None, warn=False):
    """Ravel column or 1d numpy array, else raise an error."""
    y = np.asarray(y, dtype=dtype)
    shape = y.shape
    if len(shape) == 1:
        return y
    if len(shape) == 2 and shape[1] == 1:
        return y.ravel()
    raise ValueError("y should be a 1d array or a column vector, "
                     "got an array of shape %s instead." % str(shape))


def safe_indexing(X, indices):
    """Index arrays or lists safely."""
    if hasattr(X, 'iloc'):
        # pandas-like
        return X.iloc[indices]
    X = np.asarray(X)
    return X[indices]


def indexable(*iterables):
    """Check that all iterables are indexable (have __getitem__ or are None).

    Returns the inputs as-is if valid, converting lists to arrays where needed.
    """
    result = []
    for x in iterables:
        if x is None:
            result.append(x)
        elif hasattr(x, '__getitem__') or hasattr(x, 'iloc'):
            result.append(x)
        else:
            result.append(np.array(list(x)))
    return result


# ─── Stub base for upstream-only estimator classes ─────────────────


class _StubEstimator:
    """Permissive estimator base used by the auto-generated stubs.
    Records constructor kwargs; fit/transform/predict return sensible
    defaults (self, the input, or zeros) so calling code doesn't crash."""

    def __init__(self, *args, **kwargs):
        # Many real sklearn wrapper estimators (RFE, RFECV, OneVsRest,
        # CalibratedClassifierCV, …) take a base estimator as the first
        # positional arg. Accepting *args and stashing them on self._args
        # — plus exposing args[0] as ``self.estimator`` when there's just
        # one — keeps these stubs constructible without per-subclass code.
        self._args = args
        if len(args) == 1 and 'estimator' not in kwargs:
            self.estimator = args[0]
        for k, v in kwargs.items():
            setattr(self, k, v)

    def fit(self, X, y=None, **kwargs):
        try:
            import numpy as _np
            X = _np.asarray(X)
            self.n_features_in_ = X.shape[1] if X.ndim > 1 else 1
        except Exception:
            pass
        return self

    def fit_transform(self, X, y=None, **kwargs):
        self.fit(X, y, **kwargs)
        return self.transform(X)

    def transform(self, X):
        import numpy as _np
        return _np.asarray(X)

    def predict(self, X):
        import numpy as _np
        X = _np.asarray(X)
        return _np.zeros(len(X))

    def predict_proba(self, X):
        import numpy as _np
        X = _np.asarray(X)
        return _np.full((len(X), 2), 0.5)

    def score(self, X, y, **kwargs):
        return 0.0

    def get_params(self, deep=True):
        return {k: v for k, v in vars(self).items() if not k.startswith('_')}

    def set_params(self, **params):
        for k, v in params.items():
            setattr(self, k, v)
        return self



